inline std::expected<int32_t, ::tpy::StopIteration> __gen_Summer_pair::__next__() {
    while (true) switch (__state) {
    case S_INITIAL: {  // entry
        __state = S_RESUME_0;
        return (::tpy::add_check<int32_t>(__self.base, ::tpy::__getitem__(xs, 0)));
    }
    case S_RESUME_0: {  // after: yield self.base + xs[0]
        __state = S_RESUME_1;
        return (::tpy::add_check<int32_t>(__self.base, ::tpy::__getitem__(xs, (::tpy::sub_check<int32_t>(::tpy::__len__(xs), 1)))));
    }
    case S_RESUME_1: {  // after: yield self.base + xs[len(xs) - 1]
        __state = S_DONE;
        return ::tpy::make_unexpected(::tpy::StopIteration{});
    }
    case S_DONE: return ::tpy::make_unexpected(::tpy::StopIteration{});
    }
    __builtin_unreachable();
}

// def run(self) -> Iterator[str]:
//     yield self.prefix                             # -> S_RESUME_0
//     for v in head_tail(make_str(2)):  # tpyc: ok
//         yield self.prefix + v                     # -> S_RESUME_1
inline std::expected<std::string, ::tpy::StopIteration> __gen_Outer_run::__next__() {
    while (true) switch (__state) {
    case S_INITIAL: {  // entry
        __state = S_RESUME_0;
        return __self.prefix;
    }
    case S_RESUME_0: {  // after: yield self.prefix
        __coro_arg_0 = ::tpyapp::main::make_str(2);
        __for_src_0.emplace(::tpyapp::main::head_tail(__coro_arg_0));
        __state = S_JOIN_0;
        continue;
    }
    case S_RESUME_1:  // after: yield self.prefix + v
    case S_JOIN_0: {
        __for_r_0.emplace((*__for_src_0).__next__());
        if (!(*__for_r_0).has_value()) {
            __state = S_DONE;
            return ::tpy::make_unexpected(::tpy::StopIteration{});
        }
        v = ::tpy::unwrap_ref(*(*__for_r_0));
        __state = S_RESUME_1;
        return (::tpy::str_concat(__self.prefix, v));
    }
    case S_DONE: return ::tpy::make_unexpected(::tpy::StopIteration{});
    }
    __builtin_unreachable();
}

